<section class="panel"><div class="panel-head"><div><h2>Buying guides</h2><p>Create ranked product recommendations such as “Best 10 ACs Under ₹40,000”.</p></div><a class="primary-button" href="<?= e(url('admin/guides/new')) ?>">+ New guide</a></div><table class="data-table"><thead><tr><th>Guide</th><th>Category</th><th>Products</th><th>Status</th><th>Updated</th><th></th></tr></thead><tbody><?php foreach($guides as $g):?><tr><td><strong><?= e($g['title']) ?></strong><small>/guide/<?= e($g['slug']) ?></small></td><td><?= e($g['category_name'] ?? '—') ?></td><td><?= (int)$g['product_count'] ?></td><td><span class="badge"><?= e($g['status']) ?></span></td><td><?= e($g['updated_at']) ?></td><td><a href="<?= e(url('admin/guides/'.(int)$g['id'].'/edit')) ?>">Edit</a></td></tr><?php endforeach;?><?php if(!$guides):?><tr><td colspan="6" class="empty">No buying guides yet.</td></tr><?php endif;?></tbody></table></section>